messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>low-poly humanoid walk/run cycle</title>
  <style>
    body { margin: 0; overflow: hidden; background: #222; }
    #info {
      position: absolute; bottom: 10px; left: 10px; color: #ccc;
      font-family: monospace; font-size: 12px; background: rgba(0,0,0,0.5); padding: 4px 8px; border-radius: 4px;
    }
  </style>
</head>
<body>
  <div id="info">🚶 2s stand → 3s walk → 3s run → 2s stand</div>
  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>
  <script type="module">
    import * as THREE from 'three';

    // --- setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x2a2a3a);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(4, 2, 6);
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // --- lights ---
    const ambient = new THREE.AmbientLight(0x404060);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
    dirLight.position.set(5, 8, 7);
    scene.add(dirLight);

    const fillLight = new THREE.DirectionalLight(0x4488ff, 0.5);
    fillLight.position.set(-3, 2, 5);
    scene.add(fillLight);

    // --- ground (treadmill-style) ---
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x3a4a5a,
      roughness: 0.8,
      flatShading: true,
    });
    const ground = new THREE.Mesh(new THREE.BoxGeometry(6, 0.2, 3), groundMat);
    ground.position.y = -0.7;
    scene.add(ground);

    // subtle grid lines
    const gridMat = new THREE.LineBasicMaterial({ color: 0x5a6a7a });
    const gridGeo = new THREE.GridHelper(6, 8, 0x5a6a7a, 0x3a4a5a);
    gridGeo.position.y = -0.6;
    scene.add(gridGeo);

    // --- build low-poly humanoid ---
    const group = new THREE.Group();
    group.position.y = 0;

    // body parts (all use flatShading for low-poly look)
    const matSkin = new THREE.MeshStandardMaterial({ color: 0x7dc4c4, flatShading: true });
    const matShirt = new THREE.MeshStandardMaterial({ color: 0x3a6e8c, flatShading: true });
    const matPants = new THREE.MeshStandardMaterial({ color: 0x2a4a5a, flatShading: true });
    const matShoe = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });
    const matHead = new THREE.MeshStandardMaterial({ color: 0x8fd4d4, flatShading: true });

    // torso (shirt)
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.2, 0.5), matShirt);
    torso.position.y = 0.6;
    group.add(torso);

    // head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 0.6), matHead);
    head.position.y = 1.3;
    head.position.z = 0.05;
    group.add(head);

    // left arm (upper + lower)
    const leftUpper = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), matSkin);
    leftUpper.position.set(-0.65, 0.9, 0);
    group.add(leftUpper);
    const leftLower = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.7, 0.25), matSkin);
    leftLower.position.set(-0.65, 0.2, 0);
    group.add(leftLower);

    // right arm
    const rightUpper = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), matSkin);
    rightUpper.position.set(0.65, 0.9, 0);
    group.add(rightUpper);
    const rightLower = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.7, 0.25), matSkin);
    rightLower.position.set(0.65, 0.2, 0);
    group.add(rightLower);

    // left leg (thigh + shin + foot)
    const leftThigh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), matPants);
    leftThigh.position.set(-0.3, -0.4, 0);
    group.add(leftThigh);
    const leftShin = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), matPants);
    leftShin.position.set(-0.3, -1.1, 0);
    group.add(leftShin);
    const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.15, 0.4), matShoe);
    leftFoot.position.set(-0.3, -1.6, 0.1);
    group.add(leftFoot);

    // right leg
    const rightThigh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.3), matPants);
    rightThigh.position.set(0.3, -0.4, 0);
    group.add(rightThigh);
    const rightShin = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.8, 0.25), matPants);
    rightShin.position.set(0.3, -1.1, 0);
    group.add(rightShin);
    const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.15, 0.4), matShoe);
    rightFoot.position.set(0.3, -1.6, 0.1);
    group.add(rightFoot);

    // store limbs for animation
    const limbs = {
      leftUpper, leftLower, rightUpper, rightLower,
      leftThigh, leftShin, rightThigh, rightShin,
      leftFoot, rightFoot,
      torso, head,
    };

    // initial offsets (used for relative rotation)
    // set pivot groups: each limb rotates around its top joint.
    // we'll reposition children so that rotation origin is at joint.

    // helper: create a pivot group for a limb, attach mesh to it, and add to group
    function pivotLimb(mesh, pivotY, parent) {
      const pivot = new THREE.Group();
      pivot.position.copy(mesh.position);
      // adjust mesh position relative to pivot
      mesh.position.y = 0;
      mesh.position.x = 0;
      mesh.position.z = 0;
      pivot.add(mesh);
      parent.add(pivot);
      return pivot;
    }

    // rebuild limbs with pivot groups
    // clear old meshes from group (we'll re-add)
    // but simpler: we just re-structure by creating pivots and transferring meshes.

    // We'll extract meshes and re-attach to pivots.
    const limbMeshes = {
      leftUpper, leftLower, rightUpper, rightLower,
      leftThigh, leftShin, rightThigh, rightShin,
      leftFoot, rightFoot,
    };

    // remove meshes from group (they are currently direct children)
    Object.values(limbMeshes).forEach(m => group.remove(m));

    // create pivots and attach
    // arms: pivot at shoulder (y ~1.0) and elbow (y ~0.4)
    const leftArmPivot = new THREE.Group();
    leftArmPivot.position.set(-0.65, 1.0, 0);
    leftUpper.position.set(0, -0.4, 0); // relative to pivot
    leftArmPivot.add(leftUpper);
    group.add(leftArmPivot);

    const leftElbowPivot = new THREE.Group();
    leftElbowPivot.position.set(-0.65, 0.4, 0);
    leftLower.position.set(0, -0.35, 0);
    leftElbowPivot.add(leftLower);
    group.add(leftElbowPivot);

    const rightArmPivot = new THREE.Group();
    rightArmPivot.position.set(0.65, 1.0, 0);
    rightUpper.position.set(0, -0.4, 0);
    rightArmPivot.add(rightUpper);
    group.add(rightArmPivot);

    const rightElbowPivot = new THREE.Group();
    rightElbowPivot.position.set(0.65, 0.4, 0);
    rightLower.position.set(0, -0.35, 0);
    rightElbowPivot.add(rightLower);
    group.add(rightElbowPivot);

    // legs: pivot at hip (y ~0.0) and knee (y ~-0.7)
    const leftHipPivot = new THREE.Group();
    leftHipPivot.position.set(-0.3, 0.0, 0);
    leftThigh.position.set(0, -0.45, 0);
    leftHipPivot.add(leftThigh);
    group.add(leftHipPivot);

    const leftKneePivot = new THREE.Group();
    leftKneePivot.position.set(-0.3, -0.9, 0);
    leftShin.position.set(0, -0.4, 0);
    leftKneePivot.add(leftShin);
    group.add(leftKneePivot);

    // foot attached to shin pivot? easier: attach foot to shin pivot directly
    leftFoot.position.set(0, -0.9, 0.1);
    leftKneePivot.add(leftFoot);

    const rightHipPivot = new THREE.Group();
    rightHipPivot.position.set(0.3, 0.0, 0);
    rightThigh.position.set(0, -0.45, 0);
    rightHipPivot.add(rightThigh);
    group.add(rightHipPivot);

    const rightKneePivot = new THREE.Group();
    rightKneePivot.position.set(0.3, -0.9, 0);
    rightShin.position.set(0, -0.4, 0);
    rightKneePivot.add(rightShin);
    group.add(rightKneePivot);

    rightFoot.position.set(0, -0.9, 0.1);
    rightKneePivot.add(rightFoot);

    // store pivots for animation
    const pivots = {
      leftArmPivot, leftElbowPivot, rightArmPivot, rightElbowPivot,
      leftHipPivot, leftKneePivot, rightHipPivot, rightKneePivot,
    };

    // add torso and head (they are static relative to group)
    // torso already added, head already added.
    // we can add lean to torso later.

    scene.add(group);

    // --- animation state ---
    const clock = new THREE.Clock();
    const cycleDuration = 10; // 2+3+3+2 = 10

    // keyframes: stand (0-2), walk (2-5), run (5-8), stand (8-10)
    function getPhase(t) {
      const cycle = cycleDuration;
      let time = t % cycle;
      if (time < 2) return { phase: 'stand', t: time / 2 };
      else if (time < 5) return { phase: 'walk', t: (time - 2) / 3 };
      else if (time < 8) return { phase: 'run', t: (time - 5) / 3 };
      else return { phase: 'stand', t: (time - 8) / 2 };
    }

    // --- animation helpers ---
    function easeInOut(t) {
      return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    }

    function sinEase(t, freq = 1) {
      return Math.sin(t * Math.PI * 2 * freq);
    }

    // --- animate ---
    function animate() {
      const delta = clock.getDelta();
      const elapsed = performance.now() / 1000; // seconds
      const phaseInfo = getPhase(elapsed);

      let standStill = false;
      let walkFactor = 0;
      let runFactor = 0;
      let leanAngle = 0;

      if (phaseInfo.phase === 'stand') {
        standStill = true;
        // reset all angles to 0
        // we'll just set everything to 0
      } else if (phaseInfo.phase === 'walk') {
        walkFactor = 1;
        runFactor = 0;
        leanAngle = 0;
      } else if (phaseInfo.phase === 'run') {
        runFactor = 1;
        walkFactor = 0;
        leanAngle = -0.15; // forward lean (radians)
      }

      // compute cyclic time for limb oscillation (0 to 1)
      let cycleTime = 0;
      if (!standStill) {
        // use a 1-second cycle for walk (slower) and 0.6s for run (faster)
        const speed = phaseInfo.phase === 'walk' ? 0.8 : 1.6;
        const raw = (elapsed * speed) % 1;
        cycleTime = raw;
      }

      // --- limb angles ---
      // walk: moderate swing, run: large swing
      let armSwing = 0;
      let legSwing = 0;
      let elbowSwing = 0;
      let kneeSwing = 0;
      if (standStill) {
        armSwing = 0; legSwing = 0; elbowSwing = 0; kneeSwing = 0;
      } else {
        const amp = phaseInfo.phase === 'walk' ? 0.5 : 1.0;
        const freq = phaseInfo.phase === 'walk' ? 1 : 1.8;
        const phase = cycleTime * Math.PI * 2 * freq;
        // arms swing opposite to legs
        armSwing = Math.sin(phase) * amp;
        legSwing = Math.sin(phase + Math.PI) * amp; // opposite
        // elbows bend more in run
        elbowSwing = phaseInfo.phase === 'run' ? Math.sin(phase + 0.5) * 0.8 : Math.sin(phase + 0.5) * 0.3;
        kneeSwing = phaseInfo.phase === 'run' ? Math.sin(phase + Math.PI + 0.5) * 0.9 : Math.sin(phase + Math.PI + 0.5) * 0.4;
      }

      // apply rotations (all relative to parent pivot)
      // arms: shoulder rotation (around Z axis for side view)
      pivots.leftArmPivot.rotation.z = armSwing;
      pivots.rightArmPivot.rotation.z = -armSwing; // mirror
      // elbows
      pivots.leftElbowPivot.rotation.z = elbowSwing;
      pivots.rightElbowPivot.rotation.z = -elbowSwing;

      // legs: hip rotation
      pivots.leftHipPivot.rotation.z = legSwing;
      pivots.rightHipPivot.rotation.z = -legSwing;
      // knees
      pivots.leftKneePivot.rotation.z = kneeSwing;
      pivots.rightKneePivot.rotation.z = -kneeSwing;

      // forward lean (torso + head)
      if (standStill) {
        group.children.forEach(child => {
          if (child === torso || child === head) {
            child.rotation.x = 0;
          }
        });
        // also reset any lean on group? no
        group.rotation.x = 0;
      } else {
        // lean whole body forward slightly for run, none for walk
        const lean = phaseInfo.phase === 'run' ? -0.15 : 0;
        group.rotation.x = lean;
      }

      // additional foot offset (slight lift) - we can adjust foot height via knee pivot
      // already included in knee swing.

      // render
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // --- resize ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
